from html import escape
from pathlib import Path
groups = {
'Color properties': [
('Hue','The basic color family, such as red, green, or blue.'),('Saturation','The intensity of a color. Higher saturation generally appears vivid; lower saturation appears muted or grayish.'),('Value','How light or dark a color appears. Higher values are lighter; lower values are darker.'),('Tint','Traditionally, a color mixed with white.'),('Shade','Traditionally, a color mixed with black.'),('Tone','Traditionally, a color mixed with gray. Digital tools may use tint, shade, and tone differently.'),('Color temperature','A way to describe colors as relatively warm or cool. A warm off-white may feel more inviting than a cooler one.')],
'Palettes and relationships': [
('Color palette','A collection of colors chosen to work together. A color wheel can help explore combinations.'),('Color relationships','How colors interact visually. For example, warm colors can balance cooler colors.'),('Color harmony','A way of describing how colors relate visually and work together. A color wheel can help, but harmony also depends on context and judgment.'),('Complementary colors','Two hues opposite each other on a color wheel, such as blue and orange on a traditional wheel. They can create strong visual contrast.'),('Analogous colors','Hues next to each other on a color wheel, such as blue, cyan, and green. They can feel unified, but similar saturation and value can make hierarchy harder to establish.'),('Triadic colors','Three hues spaced approximately equally around a color wheel. They can create variety and energy, but giving each equal visual weight may feel busy.'),('Split-complementary colors','A base hue and the two hues on either side of its complement. For example, a traditional wheel can pair blue with yellow-orange and red-orange.'),('Square color harmony','Four hues spaced approximately equally around a color wheel. They offer variety and more opportunities for colors to compete. A palette does not require every hue in every component.'),('Palette size','How many distinct colors are available. More colors can be intentional and expressive; the goal is to avoid unnecessary complexity.'),('Palette efficiency','How effectively a palette provides the needed variety. A few foundational hues can produce many variations through tints, shades, and tones.'),('Palette distribution','How much space and attention each color receives. A primary brand color does not need to dominate every component.'),('60-30-10 rule','A heuristic for distributing dominant, secondary, and accent colors. It is not an accessibility standard or a mathematical requirement, and proportions alone do not establish hierarchy.'),('Color placement','Where a color appears. Placement can affect what people notice as much as the amount of color used.'),('Prominence','How much an element stands out in relation to its surroundings.'),('Color vibration','A visually unstable or uncomfortable effect that can occur when highly saturated colors with similar perceived brightness sit next to each other. Check measurable text contrast and visual comfort separately.')],
'Interface color roles': [
('Accent color','A supporting color used selectively to highlight elements or add variety. It does not have to be complementary to the primary color.'),('Supporting colors','Colors used alongside a primary color to provide balance, hierarchy, or variety.'),('Neutral colors','Colors such as white, black, gray, and near-neutral variations. They influence an interface’s atmosphere even when they receive little attention.'),('Semantic color','A color used to communicate a purpose or meaning in an interface, such as an error state.'),('Semantic color system','A system that assigns colors responsibilities instead of choosing them solely for appearance. Do not rely on color alone to communicate meaning.'),('Visual hierarchy','The arrangement of elements that helps people understand their relative importance. Color is one of several tools for establishing hierarchy.'),('Brand identity','The recognizable qualities of a brand. Existing and new colors should support or deliberately evolve that identity.'),('Design consistency','Applying choices predictably according to their roles. Consistency does not require every component to use the same color.')],
'Design systems and tokens': [
('Design system','A shared collection of principles, components, and guidance that helps a team create consistent experiences, including rules for color.'),('Design token','A reusable, named design decision, such as a color or spacing value. A small set of foundational colors can support many variations and roles.'),('Color token','A design token that represents a color value or a color’s purpose.'),('Primitive token','A named foundational value, such as pink-500: #EC4899.'),('Semantic token','A named purpose that references a value, such as action-primary-background referencing pink-500. This separates the purpose from the underlying color.'),('Paired semantic tokens','Related role tokens used together, such as a background and the text displayed on it. Check the contrast of the actual pair.'),('Contextual semantic token','A role token that also identifies the context in which it is used, such as text on a dark surface.'),('Component token','A token for a specific component, such as button-primary-background. It can provide customization but adds complexity; more layers are not automatically better.'),('Component variant','A named version of a component that serves a distinct purpose, such as a featured button. Its styles can reference semantic tokens.'),('Semantic variant and contextual override','A semantic variant describes why a component differs; a contextual override describes where a difference applies.'),('Token reference','A connection between tokens or between a token and a component. Following references helps determine which elements change when a color is updated.')],
'Accessibility and evaluation': [
('Contrast','The visual difference between elements, such as text and its background, that helps distinguish them.'),('Contrast ratio','A measurement of the difference in relative luminance between two colors.'),('Text contrast','WCAG AA generally requires a contrast ratio of at least 4.5:1 for normal text and 3:1 for large text. Large text is at least 18pt regular or 14pt bold; exceptions apply.'),('Readability','How easy text is to read. Contrast, typography, size, spacing, and layout all contribute. Passing a contrast check alone does not guarantee readability.'),('Visual comfort','Whether a combination feels stable and comfortable to look at. Evaluate it alongside measurable contrast.'),('User research','Ways to learn about users and their needs, including observing people and gathering feedback. Analytics can help identify potential problems.'),('User goals','What visitors are trying to accomplish. Compare observed behavior with those goals before interpreting results.'),('Problem identification','Define what needs to improve before choosing a solution, such as changing a palette.')],
'Psychology and interpretation': [
('Color psychology','The study and discussion of how people perceive and respond to colors, including possible emotional associations.'),('Color association','An idea or feeling a color may bring to mind. Red, for example, can suggest urgency or passion.'),('Color interpretation','The meaning someone takes from a color in context. A vivid red can suggest energy, burgundy elegance, and a light red softness; interpretations vary.')]
}
associations=[('Red','Danger, urgency, passion, love'),('Orange','Energy, warmth, enthusiasm'),('Yellow','Optimism, happiness, caution'),('Green','Nature, growth, health, success'),('Blue','Trust, calmness, reliability'),('Purple','Creativity, luxury, spirituality'),('Pink','Romance, sensitivity, playfulness'),('Black','Power, sophistication, elegance'),('White','Simplicity, cleanliness, purity'),('Gray','Neutrality, professionalism, restraint')]
groups['Color properties'].extend([('Color scale','A sequence of related color variations, often used to support different roles and states.'), ('Brightness and lightness','Related ways to describe perceived intensity and lightness, but they are not always technically identical.')])
groups['Interface color roles'].extend([('Visual cue','A signal that helps someone identify, interpret, or use an element, such as a label, icon, shape, or placement.'), ('Coverage','How much space a color occupies.'), ('Frequency','How often a color appears. Repetition can influence its perceived importance.'), ('Interactive state','A condition of a control, such as default, hover, focus, pressed, or disabled.'), ('Hover','A state that can indicate pointer interaction. Touch users may not have a hover state.'), ('Focus','The state identifying the element ready to receive input, often shown with a visible focus indicator.'), ('Iterative design','A process of reviewing, testing, and refining a design. Changing one variable at a time can help isolate its effect.')])
slug=lambda s: ''.join(c.lower() if c.isalnum() else '-' for c in s).strip('-')
sections=[]
for name, entries in groups.items():
 rows=''.join(f'<div class="vocab-entry"><dt>{escape(term)}</dt><dd><p>{escape(desc)}</p></dd></div>' for term,desc in entries)
 sections.append(f'<section class="vocab-group" data-topic="{escape(name)}"><div class="vocab-group-heading"><h2>{escape(name)}</h2></div><dl>{rows}</dl></section>')
options=''.join(f'<option>{escape(n)}</option>' for n in groups)
colors=''.join(f'<tr><th scope="row">{escape(c)}</th><td>{escape(a)}</td></tr>' for c,a in associations)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explore color vocabulary and practical design notes."><title>Color vocabulary | Color Learning</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="navigation.css?v=2"><link rel="stylesheet" href="vocabulary.css"><link rel="stylesheet" href="custom.css?v=2"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a class="brand" href="./" aria-label="Color Learning home"><span class="brand-mark" aria-hidden="true">C</span><b>Color Learning</b></a><nav id="site-navigation" class="nav-links" aria-label="Main navigation"><a href="#main" aria-current="page">Vocabulary</a><a href="notes.html">Design notes</a><a href="#associations">Color associations</a><a href="#future">Future ideas</a></nav><button id="nav-toggle" class="nav-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="site-navigation"><span aria-hidden="true"></span><span aria-hidden="true"></span><span aria-hidden="true"></span></button></div></header><main id="main"><section class="intro"><h1>Color vocabulary</h1><div class="intro-bottom"><p>Explore the terms, relationships, and practical ideas behind color in design.</p></div></section><div class="vocab-filters"><label for="vocab-search">Find a term<input type="search" id="vocab-search" placeholder="Search terms and definitions…"></label><label for="vocab-topic">Topic<select id="vocab-topic"><option value="">All topics</option>'''+options+'''</select></label><button id="vocab-clear" type="button">Clear filters</button></div><p id="vocab-count" role="status"></p><div id="vocab-groups">'''+''.join(sections)+'''</div><p id="vocab-empty" hidden>No matching terms. Try another search or topic.</p><section id="associations" class="vocab-sources"><h2>Common color associations</h2><p>These are possible associations, not universal meanings. Culture, experience, saturation, lightness, and surrounding colors can change interpretation.</p><div class="table-wrap"><table><thead><tr><th scope="col">Color</th><th scope="col">Possible associations</th></tr></thead><tbody>'''+colors+'''</tbody></table></div><p>Based on your notes from a freeCodeCamp article. The specific article can be linked when its URL is available.</p></section><section id="future" class="vocab-sources"><h2>Future idea: describe a website’s colors</h2><p>Build a vocabulary of descriptors across scales such as warm to cool, muted to vivid, light to dark, and restrained to energetic. A future website analysis could use these descriptors with a person reviewing and adjusting the interpretation.</p></section></main><footer><p>Color Learning · Vocabulary in progress</p></footer><script src="navigation.js?v=2"></script><script src="app.js"></script></body></html>'''
words = "sophistication, exclusivity, softness, warmth, earthiness, approachability, excitement, warning, happiness, optimism, prestige, vintage, playfulness, attention, caution, cheerful, luxury, tradition, gold, nature, growth, renewal, calmness, success, confirmation, money, wealth, environmental responsibility, trust, stability, professionalism, technology, authority, openness, safe, welcome, reassurance, affection, romance, gentle, rich, bold, strength, confidence, power, understated, dramatic, refined, restrained, clean, minimal, simplicity, modern, inviting, impersonal, sterile, unwelcoming, dull, distant, lifeless, balance, elegant".split(", ")
word_items = ''.join(f'<li>{escape(word)}</li>' for word in words)
word_bank = '<section id="word-bank" class="vocab-sources"><h2>Color and feeling word bank</h2><p>Words to describe possible associations and the feeling of a website. These are starting points for interpretation, not fixed meanings of colors. Context and personal experience matter.</p><ul class="word-bank">' + word_items + '</ul><p>Gold is included as a color or material association. We can refine categories and scales as this collection grows.</p></section>'
html = html.replace('<section id="future"', word_bank + '<section id="future"')
Path('dist/index.html').write_text(html)
